insert into public.receta_pasos values ('b13edc4b-2461-5f6f-95ae-ace5a2aea7b0', 1, 'Uní la harina con el polvo de hornear en un bol.') on conflict do nothing;
insert into public.receta_pasos values ('b13edc4b-2461-5f6f-95ae-ace5a2aea7b0', 2, 'Sumá el huevo, el yogur, el aceite, el endulzante y la vainilla, y trabajá hasta tener una masa blanda.') on conflict do nothing;
insert into public.receta_pasos values ('b13edc4b-2461-5f6f-95ae-ace5a2aea7b0', 3, 'Estirala fina en forma de rectángulo y cortá triángulos.') on conflict do nothing;
insert into public.receta_pasos values ('b13edc4b-2461-5f6f-95ae-ace5a2aea7b0', 4, 'Enrollá cada triángulo desde el lado ancho hacia la punta.') on conflict do nothing;
insert into public.receta_pasos values ('b13edc4b-2461-5f6f-95ae-ace5a2aea7b0', 5, 'Pintalas con la yema y acomodalas sobre papel manteca en la canasta.') on conflict do nothing;
insert into public.receta_pasos values ('b13edc4b-2461-5f6f-95ae-ace5a2aea7b0', 6, 'Cociná 10 a 12 minutos a 170 °C. No hace falta darlas vuelta.') on conflict do nothing;
