insert into public.receta_pasos values ('ac1748b7-7f42-5efe-b126-3989270e9171', 2, 'Agregá la harina, el aceite y la sal, y uní hasta tener una masa pareja.') on conflict do nothing;
insert into public.receta_pasos values ('ac1748b7-7f42-5efe-b126-3989270e9171', 3, 'Tapala y dejala levar alrededor de una hora, hasta que duplique el volumen.') on conflict do nothing;
insert into public.receta_pasos values ('ac1748b7-7f42-5efe-b126-3989270e9171', 4, 'Pasala a un molde que entre en la freidora, pincelala con aceite y hacele unos tajos arriba.') on conflict do nothing;
insert into public.receta_pasos values ('ac1748b7-7f42-5efe-b126-3989270e9171', 5, 'Cociná 20 minutos a 170 °C, girando el molde a mitad de tiempo para que se dore parejo.') on conflict do nothing;
